 function photoTabs(path,hi){const tabs=[["photo-studio","Studio","स्टूडियो"],["background-changer","Background","बैकग्राउंड"],["crop","Crop","क्रॉप"],["resize","Resolution","रिज़ॉल्यूशन"],["compress","Compress","KB कम करें"],["photo-sheet","Photo frames","फोटो फ्रेम"],["convert","Format","फॉर्मेट"],["inspect","Check size","साइज़ जांचें"]],slug=path.split("/").filter(Boolean).at(-1),prefix=hi?"/hi":"";if(![...tabs.map(x=>x[0]),"passport","signature"].includes(slug))return "";return '<nav class="photo-tabs" aria-label="'+(hi?"फोटो एडिटिंग":"Photo editing")+'">'+tabs.map(([id,en,hn])=>'<a href="'+prefix+'/tools/'+id+'/"'+(slug===id?' aria-current="page"':'')+'>'+toolIcon(id)+'<span>'+(hi?hn:en)+'</span></a>').join("")+'</nav>';}
