 const hi=path.startsWith('/hi/'),enPath=hi?path.slice(3):path,hiPath='/hi'+enPath,prefix=hi?'/hi':'',other=hi?enPath:hiPath;const tr=(a,b)=>hi?b:a;
 const libs=(path.includes('/qr/')||path.includes('/upi-qr/'))?'<script src="/assets/vendor/qrcode.js" defer></script>':(path.includes('/scan-pdf/')||path.includes('/image-text/')||path.includes('/mask-aadhaar/'))?'<script src="/assets/vendor/tesseract/tesseract.min.js" defer></script>':path.includes('/krutidev-unicode/')?'<script src="/assets/krutidev.js" defer></script>':path.includes('/typing-test/')?'<script src="/assets/krutidev.js" defer></script><script src="/assets/typing.js" defer></script>':path.includes('/resume-maker/')?'<script src="/assets/resume.js" defer></script>':(path.includes('-calculator/')||path.includes('/amount-in-words/'))?'<script src="/assets/calc.js" defer></script>':'';
 const canon=origin?`<link rel="canonical" href="${esc(origin+path)}"><link rel="alternate" hreflang="en" href="${esc(origin+enPath)}"><link rel="alternate" hreflang="hi" href="${esc(origin+hiPath)}"><link rel="alternate" hreflang="x-default" href="${esc(origin+enPath)}">`:'<meta name="robots" content="noindex, nofollow">';
 files["site"+path+"index.html"]=`<!doctype html><html lang="${hi?"hi":"en"}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${esc(title)} | KaagazKit</title><meta name="description" content="${esc(desc)}">${canon}${path==="/"&&verification?`<meta name="google-site-verification" content="${esc(verification)}">`:""}<link rel="icon" href="/assets/icon.svg"><link rel="manifest" href="/manifest.webmanifest"><meta name="theme-color" content="#145fbd"><link rel="apple-touch-icon" href="/assets/icon-192.png"><link rel="stylesheet" href="/assets/style.css"><script src="/assets/pwa.js" defer></script></head><body><a class="skip" href="#main">${tr("Skip to content","मुख्य सामग्री पर जाएं")}</a><header><div class="wrap nav"><a class="brand" href="${prefix}/"><img class="brand-mark" src="/assets/icon.svg" alt="" width="34" height="34"><b class="brand-name">Kaagaz<span>Kit</span></b></a><nav aria-label="${tr("Main navigation","मुख्य नेविगेशन")}"><a href="${prefix}/#tools">${tr("Tools","टूल्स")}</a><a href="${prefix}/privacy/">${tr("Privacy","गोपनीयता")}</a><a href="${prefix}/about/">${tr("About","हमारे बारे में")}</a><a class="language" href="${other}" lang="${hi?"en":"hi"}" hreflang="${hi?"en":"hi"}">${tr("हिंदी","English")}</a></nav></div></header><main class="wrap" id="main">${tool?photoTabs(path,hi):""}${body}</main><footer class="wrap"><p>KaagazKit · ${tr("Independent browser utilities","स्वतंत्र ब्राउज़र टूल्स")}</p><a href="${prefix}/privacy/">${tr("Privacy","गोपनीयता")}</a> · <a href="${prefix}/terms/">${tr("Terms","शर्तें")}</a> · <a href="${prefix}/about/">${tr("About","हमारे बारे में")}</a> · <a href="/assets/vendor/THIRD-PARTY-LICENSES.txt">${tr("Open-source notices","ओपन सोर्स लाइसेंस")}</a></footer>${libs}${(path==="/"||path==="/hi/")?'<script src="/assets/library.js" defer></script>':""}${tool?(path.includes("/photo-studio/")?'<script src="/assets/photo-studio.js" defer></script>':path.includes("/background-changer/")?'<script src="/assets/background.js" defer></script>':'<script src="/assets/tools.js" defer></script>'):''}</body></html>`;
