 function library(hi=false){const list=hi?hindi:catalog,prefix=hi?"/hi":"";return '<div class="library-heading"><h2>'+(hi?"सभी टूल्स":"All tools")+'</h2><p>'+(hi?"मुफ्त · बिना लॉगिन":"Free · No sign-in")+'</p></div><div class="tool-search" hidden><label for="tool-search">'+(hi?"टूल खोजें":"Find a tool")+'</label><div class="search-row"><input id="tool-search" type="search" autocomplete="off" maxlength="100" placeholder="'+(hi?"जैसे फोटो 50 KB, PDF जोड़ें":"e.g. 50 KB photo, merge PDF")+'"><button type="button" id="clear-search" hidden>'+(hi?"हटाएं":"Clear")+'</button></div><p id="search-status" role="status" aria-live="polite"></p></div><div class="category-nav" aria-label="'+(hi?"टूल की श्रेणियां":"Tool categories")+'">'+toolGroups.map(([id,en,hn,slugs])=>'<a href="#group-'+id+'">'+(hi?hn:en)+' <span>'+slugs.length+'</span></a>').join("")+'</div>'+toolGroups.map(([id,en,hn,slugs])=>'<section class="tool-group" id="group-'+id+'"><h3>'+(hi?hn:en)+'</h3><div class="grid">'+slugs.map(slug=>{const entry=list.find(x=>x[0]===slug);if(!entry)throw Error("Missing tool "+slug);return '<a class="tile" data-search="'+esc([slug,entry[1],entry[2],searchAliases[slug]||"",catalog.find(x=>x[0]===slug)[1],hindi.find(x=>x[0]===slug)[1]].join(" "))+'" href="'+prefix+'/tools/'+slug+'/">'+toolIcon(slug)+'<h2>'+esc(entry[1])+'</h2></a>';}).join("")+'</div></section>').join("");}
 page("/","Free photo & PDF tools for Indian forms – no upload","Compress photos to 20–200 KB, make exam photos and signatures, merge, compress, sign and unlock PDFs, all in your browser with no upload.",`<section class="hero compact"><h1>Free photo, PDF and <em>calculator tools</em></h1><p class="sub">Files stay on your phone · Hindi and English · No sign-in</p></section><nav class="popular" aria-label="Popular tools"><h2>Most used</h2><div class="top-grid">${popular.map(([slug,en])=>'<a class="top" href="/tools/'+slug+'/">'+toolIcon(slug)+'<b>'+en+'</b></a>').join("")}</div></nav><section id="tools">${library()}</section><section class="faq"><h2>Questions</h2><details><summary>Are my files uploaded anywhere?</summary><p>No. Every tool works inside your browser on your own phone or computer. Only the website files themselves are downloaded.</p></details><details><summary>Is it really free?</summary><p>Yes. There is no account, no watermark and no paid plan.</p></details><details><summary>Will my photo be accepted by the exam form?</summary><p>The tools make files at the size you choose. Rules change between exams and years, so always compare with the official notification before uploading.</p></details><details><summary>Can I use it without internet?</summary><p>After you open the site once, most tools also work offline. You can install it like an app from your browser menu.</p></details><details><summary>Does it work in Hindi?</summary><p>Yes. Every page has a Hindi version, and text tools such as OCR and Excel to PDF support Hindi.</p></details></section><section class="info"><h2>Built for privacy</h2><p>Selected files are processed inside your browser and the results can be downloaded directly. Keep your original files.</p></section>`);
 for(const [slug,name,desc,info,action] of catalog)page(`/tools/${slug}/`,name,desc,`<p class="crumb"><a href="/">All tools</a> / ${esc(name)}</p><section class="intro">${toolIcon(slug)}<p class="eyebrow">FREE · LOCAL PROCESSING</p><h1>${esc(name)}</h1><p>${esc(desc)}</p></section><section class="panel" data-tool="${slug}"><form id="tool-form"><div id="fields" class="fields"></div><button class="button" type="submit">${esc(action)}</button></form><p id="status" role="status" aria-live="polite"></p><div id="result"></div><noscript>Enable JavaScript to use this tool.</noscript></section><section class="info"><h2>How it works</h2><p>${esc(info)}</p><p>Review the output before downloading or submitting it to a third party.</p>${slug==="compress"?'<h2>Compress a photo to 20 KB, 50 KB, 100 KB or 200 KB</h2><ol><li>Choose a JPEG, PNG or WebP image.</li><li>Choose the maximum size or enter a custom KB limit.</li><li>Allow smaller dimensions if image quality alone cannot meet the limit.</li><li>Download the JPEG and check its actual size and dimensions.</li></ol><h3>Will the image be exactly the requested size?</h3><p>No. The tool targets a maximum, not an exact byte count. It uses 1 KB = 1024 bytes. If a form uses decimal kilobytes, choose a slightly smaller limit and verify it.</p><h3>Will the original photo be changed?</h3><p>No. Keep your original. A new JPEG is created, and transparency is replaced by white.</p>':''}${guide(slug)}<a href="/#tools">Explore other tools</a></section>`,true);
 page("/privacy/","Privacy","How KaagazKit handles files and hosting data.","<h1>Privacy</h1><section class=\"info\"><p>The current tools process selected files and text in your browser. No account, file upload, advertising or analytics script is included in this release. Hosting providers may process request metadata such as IP address and user agent to deliver and secure the site.</p><p>If you email support, your email address and message are received to respond to your request. Do not send sensitive documents, passwords or identity numbers. If advertising or analytics is introduced, the privacy notice and required consent mechanisms must be updated before enabling them.</p></section>");
 page("/terms/","Terms of use","Terms for independent free utilities.","<h1>Terms of use</h1><section class=\"info\"><p>These tools are for general convenience. Keep originals and review output. No official form acceptance, uninterrupted availability or perfect image quality is guaranteed. Nothing here limits rights that cannot legally be excluded.</p><p>Use only files you have permission to process.</p></section>");
 page("/about/","About","About KaagazKit.","<h1>About</h1><section class=\"info\"><p>KaagazKit is an independent collection of twenty-one free browser utilities, not affiliated with any government or examination board.</p></section>"+(contact?`<section class="info"><h2>Contact</h2><p>For feedback or to report a problem, email <a href="mailto:${esc(contact)}">${esc(contact)}</a>.</p></section>`:'<p>Pre-launch release: operator contact information and hosting-specific policy review are required before public launch.</p>'));
 page("/hi/","फोटो KB में कम करें, PDF बनाएं – मुफ्त हिंदी टूल्स","फोटो को 20–200 KB में कम करें, परीक्षा फोटो और हस्ताक्षर बनाएं, PDF जोड़ें, छोटी करें, साइन और अनलॉक करें – बिना अपलोड, आपके ब्राउज़र में।",`<section class="hero compact"><h1>मुफ्त फोटो, PDF और <em>कैलकुलेटर टूल्स</em></h1><p class="sub">फाइलें आपके फोन में ही रहती हैं · हिंदी और अंग्रेज़ी · बिना लॉगिन</p></section><nav class="popular" aria-label="लोकप्रिय टूल्स"><h2>सबसे ज़्यादा इस्तेमाल</h2><div class="top-grid">${popular.map(([slug,,hn])=>'<a class="top" href="/hi/tools/'+slug+'/">'+toolIcon(slug)+'<b>'+hn+'</b></a>').join("")}</div></nav><section id="tools">${library(true)}</section><section class="faq"><h2>अक्सर पूछे जाने वाले सवाल</h2><details><summary>क्या मेरी फाइलें कहीं अपलोड होती हैं?</summary><p>नहीं। हर टूल आपके अपने फोन या कंप्यूटर के ब्राउज़र में चलता है। सिर्फ वेबसाइट की फाइलें डाउनलोड होती हैं।</p></details><details><summary>क्या यह सच में मुफ्त है?</summary><p>हां। कोई अकाउंट, वॉटरमार्क या पेड प्लान नहीं है।</p></details><details><summary>क्या मेरी फोटो परीक्षा फॉर्म में स्वीकार होगी?</summary><p>टूल आपके चुने साइज़ में फाइल बनाते हैं। हर परीक्षा और साल के नियम बदल सकते हैं, इसलिए अपलोड से पहले आधिकारिक अधिसूचना से जरूर मिलाएं।</p></details><details><summary>क्या बिना इंटरनेट के चलेगा?</summary><p>साइट एक बार खोलने के बाद ज्यादातर टूल ऑफलाइन भी चलते हैं। ब्राउज़र मेनू से इसे ऐप की तरह इंस्टॉल भी कर सकते हैं।</p></details><details><summary>क्या यह हिंदी में चलता है?</summary><p>हां। हर पेज हिंदी में है, और OCR व Excel से PDF जैसे टेक्स्ट टूल हिंदी समझते हैं।</p></details></section><section class="info"><h2>आपकी गोपनीयता</h2><p>चुनी हुई फाइलें आपके ब्राउज़र में प्रोसेस होती हैं। परिणाम डाउनलोड करें और मूल फाइल सुरक्षित रखें।</p></section>`);
 for(const [slug,name,desc,info,action] of hindi)page(`/hi/tools/${slug}/`,name,desc,`<p class="crumb"><a href="/hi/">सभी टूल्स</a> / ${esc(name)}</p><section class="intro">${toolIcon(slug)}<p class="eyebrow">मुफ्त · ब्राउज़र में प्रोसेसिंग</p><h1>${esc(name)}</h1><p>${esc(desc)}</p></section><section class="panel" data-tool="${slug}"><form id="tool-form"><div id="fields" class="fields"></div><button class="button" type="submit">${esc(action)}</button></form><p id="status" role="status" aria-live="polite"></p><div id="result"></div><noscript>इस टूल के लिए JavaScript चालू करें।</noscript></section><section class="info"><h2>कैसे काम करता है?</h2><p>${esc(info)}</p><p>डाउनलोड या किसी आवेदन में इस्तेमाल करने से पहले परिणाम जांचें।</p>${slug==="compress"?'<h2>फोटो को 20 KB, 50 KB, 100 KB या 200 KB कैसे करें?</h2><ol><li>अपनी JPEG, PNG या WebP फोटो चुनें।</li><li>अधिकतम KB सीमा चुनें।</li><li>जरूरत होने पर पिक्सेल आकार कम करने की अनुमति दें।</li><li>JPEG डाउनलोड करें और वास्तविक फाइल साइज़ जांचें।</li></ol><p>यह अधिकतम सीमा है, बिल्कुल उतने KB की गारंटी नहीं। यहां 1 KB = 1024 बाइट है।</p>':''}${guide(slug,true)}<a href="/hi/#tools">अन्य टूल्स देखें</a></section>`,true);
 page("/hi/privacy/","गोपनीयता","फाइल और होस्टिंग डेटा के बारे में जानकारी।",'<h1>गोपनीयता</h1><section class="info"><p>इस संस्करण में चुनी हुई फाइल और टेक्स्ट ब्राउज़र में प्रोसेस होते हैं। अकाउंट, फाइल अपलोड, विज्ञापन या एनालिटिक्स स्क्रिप्ट नहीं हैं। होस्टिंग प्रदाता साइट चलाने और सुरक्षा के लिए IP पता और ब्राउज़र जैसी अनुरोध जानकारी प्रोसेस कर सकता है।</p><p>सपोर्ट को ईमेल करने पर आपके संदेश और ईमेल पते का उपयोग जवाब देने के लिए होता है। संवेदनशील दस्तावेज, पासवर्ड या पहचान संख्या न भेजें। विज्ञापन या एनालिटिक्स शुरू करने से पहले गोपनीयता सूचना और आवश्यक सहमति व्यवस्था अपडेट होगी।</p></section>');
 page("/hi/terms/","उपयोग की शर्तें","स्वतंत्र मुफ्त टूल्स की शर्तें।",'<h1>उपयोग की शर्तें</h1><section class="info"><p>ये टूल सामान्य सुविधा के लिए हैं। मूल फाइल रखें और परिणाम जांचें। आधिकारिक स्वीकृति, लगातार उपलब्धता या पूरी गुणवत्ता की गारंटी नहीं है। कानून के तहत जिन अधिकारों को सीमित नहीं किया जा सकता वे बने रहेंगे।</p><p>केवल वे फाइलें इस्तेमाल करें जिनके लिए आपके पास अनुमति है।</p></section>');
 page("/hi/about/","हमारे बारे में","KaagazKit की जानकारी।",'<h1>हमारे बारे में</h1><section class="info"><p>KaagazKit इक्कीस स्वतंत्र मुफ्त ब्राउज़र टूल्स का संग्रह है। इसका किसी सरकारी संस्था या परीक्षा बोर्ड से संबंध नहीं है।</p></section>'+(contact?`<section class="info"><h2>संपर्क</h2><p>समस्या या सुझाव के लिए <a href="mailto:${esc(contact)}">${esc(contact)}</a> पर ईमेल करें।</p></section>`:'<p>लॉन्च से पहले संचालक की संपर्क जानकारी और होस्टिंग नीति की समीक्षा जरूरी है।</p>'));
